import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"考古协议总纲","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/84-考古协议总纲.md","filePath":"constitution/84-考古协议总纲.md"}'),o={name:"constitution/84-考古协议总纲.md"};function h(i,t,l,n,u,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="考古协议总纲" tabindex="-1">考古协议总纲 <a class="header-anchor" href="#考古协议总纲" aria-label="Permalink to &quot;考古协议总纲&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>84</td></tr><tr><td>所属模块</td><td>跨位面交互与时间规则</td></tr><tr><td>核心关键词</td><td>考古协议、复制镜、隔离空间、仅回传知识、低污染</td></tr></tbody></table><h2 id="一、考古协议的定位与目标" tabindex="-1">一、考古协议的定位与目标 <a class="header-anchor" href="#一、考古协议的定位与目标" aria-label="Permalink to &quot;一、考古协议的定位与目标&quot;">​</a></h2><p>跨位面考古与时间回溯考古是锚点共生文明获取历史知识、理解宇宙演化的重要手段。然而，考古行为本身具有高度的风险性——直接进入目标位面或目标时段进行考古发掘，可能对目标对象造成物理破坏、法则扰动与文化污染。为规范考古行为、降低考古风险，衡元宙制定了统一的《考古协议总纲》，作为一切跨位面与时间回溯考古活动的根本操作规范。</p><p>考古协议的核心目标可以概括为&quot;三个最大限度&quot;：最大限度地获取完整的历史知识，最大限度地降低对目标对象的干扰与破坏，最大限度地保障考古人员的安全。这三个目标之间存在内在的张力——知识获取的完整性往往要求更深入的接触，而低干扰原则又限制了接触的深度。考古协议的全部制度设计，都是为了在这三者之间找到最优的平衡点。</p><p>考古协议适用于以下场景：对未知位面的文明遗迹进行考古调查、通过时间回溯对已消亡文明进行历史复原、对本位面古代遗迹进行法则层面的深度考古、以及对法则破碎位面中的远古遗存进行抢救性发掘。</p><h2 id="二、考古方案的三要素" tabindex="-1">二、考古方案的三要素 <a class="header-anchor" href="#二、考古方案的三要素" aria-label="Permalink to &quot;二、考古方案的三要素&quot;">​</a></h2><p>衡元宙的标准考古方案由三个核心要素构成，被称为&quot;考古三要素&quot;：</p><h3 id="_2-1-复制镜" tabindex="-1">2.1 复制镜 <a class="header-anchor" href="#_2-1-复制镜" aria-label="Permalink to &quot;2.1 复制镜&quot;">​</a></h3><p>复制镜是一种基于空间法理法则的高精度复制装置，能够在不接触原物的前提下，对目标区域内的物质、能量与信息结构进行1:1的完整复制。复制镜的工作原理是通过空间法则扫描目标区域的全部粒子状态与能量场分布，然后在隔离空间中重建一个完全相同的副本。复制过程不改变原物的任何状态，因此不会对考古现场造成任何物理干扰。</p><p>复制镜的复制精度达到亚原子级别，能够完整还原目标区域内的物质结构、能量残留、意识印记乃至因果链碎片。复制范围可根据考古需求调整，最小复制单位为单个文物，最大可覆盖整个遗迹群。复制时间取决于复制范围的大小，单个文物的复制通常在数分钟内完成，大型遗迹群的复制可能需要数天。</p><h3 id="_2-2-隔离空间" tabindex="-1">2.2 隔离空间 <a class="header-anchor" href="#_2-2-隔离空间" aria-label="Permalink to &quot;2.2 隔离空间&quot;">​</a></h3><p>隔离空间是通过空间法理调度技术构建的独立法则区域，用于承载复制镜生成的考古副本，并作为考古人员的工作场所。隔离空间与目标位面或目标时段之间由完整的法则壁垒分隔，确保考古操作不会对原目标产生任何反向影响。</p><p>隔离空间内部的法则参数可以根据考古需求进行定制，包括：模拟目标位面的环境参数以确保文物副本的稳定、设置特殊的分析法则场以辅助考古研究、以及建立严格的污染防控场以防止考古人员的能量与意识外泄。隔离空间的大小可按需扩展，最大可容纳整个城市级别的遗迹副本。</p><h3 id="_2-3-仅回传知识" tabindex="-1">2.3 仅回传知识 <a class="header-anchor" href="#_2-3-仅回传知识" aria-label="Permalink to &quot;2.3 仅回传知识&quot;">​</a></h3><p>&quot;仅回传知识&quot;是考古协议的核心原则之一，指考古过程中从目标对象获取的只能是抽象的知识与信息，不得回传任何物质、能量或生命体。考古人员在隔离空间中对副本进行研究后，只能将研究结论、数据记录与分析报告以纯信息的形式带回本位面，副本本身以及从副本中提取的任何物质样本都必须在隔离空间内销毁。</p><p>这一原则的根本目的是防止跨位面污染与时间线扰动。即使是从副本中提取的一粒尘埃，也可能携带目标位面的法则信息，一旦进入本位面的法则网络，就可能引发不可预测的连锁反应。因此，&quot;仅回传知识&quot;不是一项可协商的操作建议，而是具有法律强制力的刚性原则。</p><h2 id="三、考古操作的标准流程" tabindex="-1">三、考古操作的标准流程 <a class="header-anchor" href="#三、考古操作的标准流程" aria-label="Permalink to &quot;三、考古操作的标准流程&quot;">​</a></h2><p>一次完整的跨位面或时间回溯考古操作遵循以下标准流程：</p><table tabindex="0"><thead><tr><th>阶段</th><th>操作内容</th><th>负责方</th><th>时长参考</th></tr></thead><tbody><tr><td>第一阶段：立项审批</td><td>提交考古申请，明确考古目标、范围与方案，获得A级穿梭许可或回溯许可</td><td>考古团队→位面管理局/时间法则委员会</td><td>7-30天</td></tr><tr><td>第二阶段：先观测</td><td>按照&quot;先观测后有限干涉&quot;准则，对目标区域进行不少于72小时的纯观测</td><td>考古团队</td><td>72小时以上</td></tr><tr><td>第三阶段：复制镜部署</td><td>在目标区域附近安全位置部署复制镜，设定复制范围与精度参数</td><td>技术组</td><td>数小时至数天</td></tr><tr><td>第四阶段：副本生成</td><td>启动复制镜，将目标区域完整复制到预建的隔离空间中</td><td>技术组</td><td>数分钟至数天</td></tr><tr><td>第五阶段：隔离空间考古</td><td>考古人员进入隔离空间，对副本进行系统的发掘、分析与研究</td><td>考古团队</td><td>数天至数年</td></tr><tr><td>第六阶段：知识整理</td><td>整理考古成果，形成研究报告与知识数据库，确保所有成果均为纯信息形式</td><td>考古团队</td><td>数天至数月</td></tr><tr><td>第七阶段：撤离与销毁</td><td>考古人员撤离隔离空间，销毁全部副本物质与能量残留，关闭隔离空间</td><td>技术组+监督组</td><td>数小时</td></tr><tr><td>第八阶段：事后审计</td><td>提交完整考古报告，接受时间法则审计委员会或位面管理局的事后审计</td><td>审计委员会</td><td>30天内</td></tr></tbody></table><h2 id="四、考古人员的资质与伦理要求" tabindex="-1">四、考古人员的资质与伦理要求 <a class="header-anchor" href="#四、考古人员的资质与伦理要求" aria-label="Permalink to &quot;四、考古人员的资质与伦理要求&quot;">​</a></h2><p>从事跨位面与时间回溯考古的人员必须具备以下资质：空间法理调度体系第三阶以上修为、通过考古伦理委员会的资格认证、完成不少于100小时的模拟考古训练、以及无任何违反共生法律的记录。</p><p>考古人员必须遵守以下伦理要求：尊重目标文明的文化与信仰，不得在研究中进行文化歧视或价值评判；保护考古现场的完整性，不得为获取文物而破坏遗迹结构；如实记录与报告考古发现，不得篡改或隐瞒考古数据；以及遵守&quot;仅回传知识&quot;原则，不得私自携带任何物质样本离开隔离空间。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>考古协议总纲是衡元宙在知识探索与文明保护之间建立的制度桥梁。它以复制镜、隔离空间与仅回传知识三要素为技术支撑，以标准化流程为操作框架，以人员资质与伦理要求为人文保障，构建了一套&quot;低污染、高效率、可追溯&quot;的考古范式。这一范式确保了衡元宙在追求历史真相的同时，始终对其他文明与时代保持最高的敬意。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>85-复制镜异地考古方案</li><li>86-隔离空间低污染流程</li><li>87-仅回传知识原则</li></ul>',27)])])}const _=a(o,[["render",h]]);export{c as __pageData,_ as default};
